    errorRender: () => authPage("إعداد التحقق بخطوتين", "", `<div class="qr" style="width:120px;height:120px"></div>${field("الرمز المكوّن من 6 أرقام", "482 118", { num: 1, req: 1, err: "رمز التحقق غير صحيح. أدخل الرمز الحالي من التطبيق." })}${full("تأكيد وتفعيل")}`),
