  const alerts = [["warn", "alert", "رحلات غير مفوترة", "86", "15,904.300", "الأقدم 2026-09-14"], ["err", "clock", "ذمم متأخرة", "9", "22,410.000", "الأقدم 2026-07-31"], ["info", "file", "مسودات بانتظار الاعتماد", "4", "3,120.800", "2026-10-08"], ["err", "x", "فواتير إلكترونية مرفوضة", "1", "1,210.400", "INV-02207"], ["warn", "clock", "ترحيلات معلّقة", "3", "—", "أقدمها قبل ساعة"], ["warn", "scale", "نقص / مخالفة تعرفة / تحتاج مراجعة", "7 · 3 · 2", "—", "هذا الشهر"], ["warn", "file", "وثائق سائقين منتهية أو تنتهي خلال 30 يوماً", "3", "—", "تأمين 10-11111 في 2026-10-28"], ["warn", "map", "مواقع تحميل بلا أسعار لشهر 2026-10", "1", "—", "الحسا"]];
